   1→import { useEffect, useState } from "react";
   2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
   3→import { useLoaderData, useFetcher } from "react-router";
   4→import { useAppBridge } from "@shopify/app-bridge-react";
   5→import { authenticate } from "../shopify.server";
   6→import db from "../db.server";
   7→
   8→// ---------------------------------------------------------------------------
   9→// Types
  10→// ---------------------------------------------------------------------------
  11→
  12→interface LocalConfig {
  13→  displayMode: string;
  14→  position: string;
  15→  triggerType: string;
  16→  primaryColor: string;
  17→  successColor: string;
  18→  errorColor: string;
  19→  backgroundColor: string;
  20→  textColor: string;
  21→  borderRadius: string;
  22→  heading: string;
  23→  placeholder: string;
  24→  buttonText: string;
  25→  successMessage: string;
  26→  errorMessage: string;
  27→  showRecommender: boolean;
  28→  customCss: string;
  29→}
  30→
  31→// ---------------------------------------------------------------------------
  32→// Loader
  33→// ---------------------------------------------------------------------------
  34→
  35→export const loader = async ({ request }: LoaderFunctionArgs) => {
  36→  const { session } = await authenticate.admin(request);
  37→  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });
  38→
  39→  return {
  40→    config: config ?? {
  41→      displayMode: "popup",
  42→      position: "bottom-right",
  43→      triggerType: "button",
  44→      primaryColor: "#000000",
  45→      successColor: "#16a34a",
  46→      errorColor: "#dc2626",
  47→      backgroundColor: "#ffffff",
  48→      textColor: "#111111",
  49→      borderRadius: "8",
  50→      heading: "Size Guide",
  51→      placeholder: "Select your size",
  52→      buttonText: "Find My Size",
  53→      successMessage: "This size should fit you well!",
  54→      errorMessage: "We couldn't determine your size. Please refer to the chart.",
  55→      showRecommender: true,
  56→      customCss: "",
  57→    },
  58→  };
  59→};
  60→
  61→// ---------------------------------------------------------------------------
  62→// Action
  63→// ---------------------------------------------------------------------------
  64→
  65→export const action = async ({ request }: ActionFunctionArgs) => {
  66→  const { session } = await authenticate.admin(request);
  67→  const formData = await request.formData();
  68→
  69→  try {
  70→    const data = {
  71→      displayMode: (formData.get("displayMode") as string) || "popup",
  72→      position: (formData.get("position") as string) || "bottom-right",
  73→      triggerType: (formData.get("triggerType") as string) || "button",
  74→      primaryColor: (formData.get("primaryColor") as string) || "#000000",
  75→      successColor: (formData.get("successColor") as string) || "#16a34a",
  76→      errorColor: (formData.get("errorColor") as string) || "#dc2626",
  77→      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
  78→      textColor: (formData.get("textColor") as string) || "#111111",
  79→      borderRadius: (formData.get("borderRadius") as string) || "8",
  80→      heading: (formData.get("heading") as string) || "Size Guide",
  81→      placeholder: (formData.get("placeholder") as string) || "Select your size",
  82→      buttonText: (formData.get("buttonText") as string) || "Find My Size",
  83→      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
  84→      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
  85→      showRecommender: formData.get("showRecommender") === "true",
  86→      customCss: (formData.get("customCss") as string) || "",
  87→    };
  88→
  89→    await db.widgetConfig.upsert({
  90→      where: { shop: session.shop },
  91→      update: data,
  92→      create: { shop: session.shop, ...data },
  93→    });
  94→    return { ok: true, message: "Widget settings saved" };
  95→  } catch (error) {
  96→    return {
  97→      error: error instanceof Error ? error.message : "An unexpected error occurred",
  98→    };
  99→  }
 100→};
